entries[438600] = { ["name"] = "Excess Frost", ["text"] = "Frost\nConsuming Excess Fire causes your next Flurry to also cast Ice Nova at 150% effectiveness. Ice Novas cast this way do not freeze enemies in place.\n\nWhen you consume Excess Frost, the cooldown of Comet Storm is reduced by 3 sec.\n\nFire\nConsuming Excess Fire causes your next Phoenix Flames to also cast Ice Nova at 200% effectiveness. Ice Novas cast this way do not freeze enemies in place.\n\nWhen you consume Excess Frost, the cooldown of Meteor is reduced by 5 sec." }
